        # Schema enforces offered IDs and the original physical choice budget.
        # Preserve MAIN's stricter selector; only this audited adapter coalesces.
        seen=set();choices=[]
        for item in raw['choices']:
            if item['id'] not in seen:choices.append(item);seen.add(item['id'])
        if len(choices)!=len(raw['choices']):
            self.s.work.event('MEMORY_SELECTION_COALESCED',{'phase':phase,'raw':raw,'executed_choices':choices})
        return {**raw,'choices':choices}
    seconds=max(1,self.s.context.remaining()-30) if record.get('law_navigation') else 240
    result=select_sources(self.host.question(state),record,select,remaining_seconds=seconds, session=self.s.sources,
        checkpoint=progress,
        on_checkpoint=getattr(self,'save_selection_progress',None))
    if result.get('status')=='pending' and not result.get('needs_fulltext'):
        failure=SourceInvestigationIncomplete(result)
        self.s.work.event('SOURCE_INVESTIGATION_INCOMPLETE',failure.diagnostics)
        if self.completion:
            from .errors import InvestigationPending
            raise InvestigationPending('질문에 필요한 원문 조사가 완료되지 않았습니다.',
                diagnostics={**failure.diagnostics,'resume_available':False,'stop_reason':result.get('stop_reason')})
        raise failure
    if result.get('needs_fulltext') or (not result['final_ids'] and read['record'].get('discovery_mode')=='structure'):
        if result.get('law_navigation'):
            self.s.sources.law_search_queries=result['search_queries']
            self.s.work.event('MEMORY_FULLTEXT_REENTRY',{'reason':'law navigation requested a new fulltext expression','selection':result})
            raise Reenter('RECALL','law navigation requested additional originals',result)
        prior=set(getattr(self.s.sources,'recall_query_plan',parts['PLAN']['payload']).get('queries',[]))
        fresh=[q for q in result.get('search_queries',[]) if q.strip() and q not in prior]
        if read['record'].get('discovery_mode')=='fulltext' and not fresh:
            raise MemoryError('source investigation incomplete: new search requires a changed query')
        if getattr(self.s.sources,'force_fulltext_recall',False) and not fresh:
            raise MemoryError('source investigation remains unresolved: unchanged search is not repeated')
        self.s.sources.additional_recall_queries=list(dict.fromkeys(getattr(self.s.sources,'additional_recall_queries',[])+fresh))
        self.s.sources.force_fulltext_recall=True
        self.s.work.event('MEMORY_FULLTEXT_REENTRY',{'reason':result.get('fallback_reason'),'selection':result})
        raise Reenter('RECALL','source selection requested additional originals',result)
    if not result['final_ids']:raise MemoryError('no relevant source selected; current question is pending')
elif stage=='ASSESS':
    read=parts['READ']['payload'];self.host.verify(read)
    selected=parts['SELECT']['payload']['final_ids'];sources=[s for s in self.selected_originals(parts) if s['source_id'] in selected]
    selection=parts['SELECT']['payload']
    data['investigation_limitations']=selection.get('completion_limitations',[])
    if self.control:
        self.issues=selection.get('issues',[{'id':'Q1','question':data['question']}])
        self.saved_material_ids=[r['material_id'] for r in selection.get('saved_inventory',[])]
        data.update(issues=self.issues,saved_inventory=selection.get('saved_inventory',[]),
            reference_navigation={k:v for k,v in selection.get('reference_navigation',{}).items() if k in ('pending','groups','unresolved','limits')},
            reentry_budget=getattr(self,'reentry_counters',{}),
            evidence_rule='saved_inventory is metadata, not quote evidence; reinspection must deliver original text before adoption',
            issue_assessment_origin='MODEL_ASSESSMENT; semantic_quality_certified=false')
    feedback=None
    for attempt in range(2):
        assessment_schema=evidence_schema(ASSESS,sources)
        if self.control:assessment_schema=ic.assess_schema(assessment_schema,self.issues,self.saved_material_ids)
        result=self.invoke(('쟁점별 status와 핵심 gaps를 기록한다. 저장되었지만 미채택한 자료를 원문 없음으로 표현하지 않는다. 보완 가능한 원문 부족은 NEEDS_INVESTIGATION, 사용자 사실 부족은 LIMITED_ANSWER와 조건부 법률 판단이다. 더 조사할 필요가 없으면 ANSWER 또는 LIMITED_ANSWER다. 무관한 미해결 연결을 일반 경고로 반복하지 않는다. 사용자가 항·호를 한정하지 않은 질문을 현재 제공된 한 항으로 임의 제한하지 않는다. 해당 규칙에 관한 다른 항의 추가 요건·예외·조건부 분기가 미열람이면 MISSING_SCOPE 또는 MISSING_SOURCE gap으로 원문 조사를 재개한다. 원문에서 확인한 조건부 추가 요건은 사건 사실이 없어도 조건과 함께 설명한다. 요구 사항을 답변 범위 밖으로 돌려 limitations에만 넣은 상태를 COVERED나 ANSWER로 표시하지 않는다. ' if self.control else '')+'현재 목적·사실과 제공된 원문으로만 판단한다. current_request는 이번 사용자의 원문 요청이다. 요약 question보다 이번 요청의 판단 범위·제외 범위·미확인 사항을 우선 보존한다. 특정 금지의 대상에서 제외됨이나 필요조건 하나의 충족을 전체 행위의 허용·적법성·충분조건으로 역추론하지 않는다. 판단 범위 밖이거나 미확인인 요건은 충족됐다고 쓰지 말고 claims의 결론 자체를 제한하고 limitations에도 명시한다. current_facts는 사용자가 제공한 판단 전제이며 법령 출처가 아니다. claims에는 원문 규칙과 그 규칙을 현재 사실에 적용한 판단을 기록한다. 사실만 진술하는 별도 claim이나 current_facts라는 출처를 만들지 않는다. source_id는 sources에 제공된 ID 중에서만 고른다. 원칙과 단서, 위임된 세칙의 예외를 함께 검토한다. claims의 text는 판단, source_id는 실제 원문 ID, quote는 해당 원문에서 한 글자도 바꾸지 않고 그대로 복사한 인용이다. 현재 사실에 없는 자격이나 기간은 확정하지 말고 조건부 결론과 limitations에 남긴다. 과거 정답은 사용하지 않는다. repair_feedback이 있으면 지적된 잘못을 원문으로 수정한다. JSON만 출력한다.',{**data,'current_request':utterance,'sources':sources,'repair_feedback':feedback},assessment_schema,'memory-assess' if not attempt else 'memory-assess-repair')
        try:
            if self.control:ic.validate_assessment(result,self.issues,self.saved_material_ids)
            if result['claims']:self.verify_claims(result['claims'],sources)
            elif not self.control:raise MemoryError('judgment contains no supported claims')
            self.s.work.event('MEMORY_SEMANTIC_REVIEW_SKIPPED',{'stage':stage,'policy':'disabled','payload_sha256':digest(result),'quality_certified':False})
            break
        except (MemoryError,ContractError) as exc:
            if attempt:raise
            feedback={'error':str(exc),'rejected_assessment':result}

    if self.control:
        actionable=[g for g in result['gaps'] if g['kind']!='MISSING_FACT']
        count=getattr(self,'reentry_counters',{}).get('ASSESS_GAP_REENTRY',0)
        limit=self.s.sources.profile['candidate_navigation']['assessment_reentry_limit']
        if result['disposition']=='NEEDS_INVESTIGATION' and actionable and count<limit:
            raise Reenter('SELECT','assessment requires additional delivered evidence',{'reentry_kind':'ASSESS_GAP_REENTRY','gaps':actionable,'assessment':result,'investigation_state':selection['investigation_state']})
        if result['disposition']=='NEEDS_INVESTIGATION':
            if not result['claims']:raise MemoryError('assessment budget exhausted without supported claims')
            result['disposition']='LIMITED_ANSWER'
        keys=set();gaps=[]
        for g in result['gaps']:
            key=digest([g['issue_id'],g['kind'],g['material_id']])
            if key not in keys:gaps.append(g);keys.add(key)
        result.update(gaps=gaps,answer_coverage=ic.coverage(result),semantic_quality_certified=False)
        result['limitations']=list(dict.fromkeys(result['limitations']+[g['reason'] for g in gaps]))
    result['limitations']=self.completion_limits(parts,result['limitations'])
else:
    assessment=parts['ASSESS']['payload'];read=parts['READ']['payload'];self.host.verify(read)

"""Durable explicit decisions and immutable menus; returning never rewinds memory."""
from copy import deepcopy
from ..contracts import digest
from .errors import ContractError

CONTRACT = 'investigation-action-chain-v1'
STRIP = {'investigation_chain', 'return_points', 'return_context', 'presentation_id'}

def state(p):
    out=p.setdefault('action_chain', {'contract':CONTRACT,'frames':{},'steps':[],'current_frame':None})
    if out.get('contract')!=CONTRACT:raise ContractError('investigation chain contract changed')
    out.setdefault('entry_frame_id', next((f['id'] for f in sorted(out['frames'].values(), key=lambda f:f['number'])), None))
    out.setdefault('arrivals', [])
    return out

def capture(p, kind, data, *, actions=None, location=None, offered=None):
    memory=state(p);raw=deepcopy({k:v for k,v in data.items() if k not in STRIP})
    payload={'kind':kind,'data':raw,'actions':deepcopy(actions or {}),
             'location':deepcopy(location or {}),'offered':deepcopy(offered or {})}
    key='H'+digest(payload)[:28]
    if key not in memory['frames']:
        memory['frames'][key]={'id':key,'number':len(memory['frames'])+1,
            'arrived_after':memory['steps'][-1]['id'] if memory['steps'] else None,**payload}
    memory['current_frame']=key
    if memory['entry_frame_id'] is None:memory['entry_frame_id']=key
    if not memory['arrivals'] or memory['arrivals'][-1]['frame_id']!=key:
        memory['arrivals'].append({'sequence':len(memory['arrivals'])+1,'frame_id':key,
                                  'after_step':memory['steps'][-1]['id'] if memory['steps'] else None})
    return key

def frame(p, key):
    try:return state(p)['frames'][key]
    except KeyError:raise ContractError('unknown historical investigation point')

def begin(p, data, decision, actions=None, *, kind='NAVIGATION'):
    memory=state(p);origin=data.get('chain_frame_id') or memory['current_frame']
    if origin not in memory['frames']:raise ContractError('decision has no bound historical menu')
    key='S'+digest({'origin':origin,'decision':decision,'turn':p.get('turn',0),'kind':kind})[:28]
    receipt=key
    old=next((x for x in reversed(memory['steps']) if x.get('receipt',x['id'])==receipt),None)
    if old and old['status'] in ('ACCEPTED','INTERRUPTED'):return old
    if old:key='S'+digest([key,len(memory['steps'])])[:28]
    targets=decision.get('targets',[])
    row={'id':key,'receipt':receipt,'number':len(memory['steps'])+1,'from_frame':origin,
         'previous_step':memory['steps'][-1]['id'] if memory['steps'] else None,
         'kind':kind,'action':decision.get('next_action','REFERENCE_CHOICES'),
         'reason':decision.get('reason','현재 제시된 연결을 선택') if kind!='REFERENCE' else '각 연결의 명시적 선택 이유를 기록',
         'targets':[deepcopy(actions[t]) for t in targets] if actions else [],
         'law_decisions':deepcopy(decision.get('law_decisions',[])),
         'branch_decisions':deepcopy(decision.get('branch_decisions',[])),
         'reference_decisions':deepcopy(decision.get('decisions',[])),
         'basis_refs':deepcopy(decision.get('basis_refs',[])),
         'queries':deepcopy(decision.get('queries',[])),
         **({'structure_filter':deepcopy(decision['structure_filter'])} if 'structure_filter' in decision else {}),
         'notes':decision.get('notes',''),'sufficiency_reason':decision.get('sufficiency_reason',''),
         'status':'ACCEPTED'}
    memory['steps'].append(row)
    return row

def context(p):
    memory=state(p)
    steps=deepcopy(memory['steps']);judgments={}
    if p.get('control_contract'):
        for step in steps:
            step['judgment_refs']=[]
            for field in ('law_decisions','branch_decisions','reference_decisions'):
                for row in step.pop(field,[]):
                    key='J'+digest({'kind':field,'decision':row})[:28]
                    judgments.setdefault(key,{'id':key,'kind':field,'decision':row})
                    step['judgment_refs'].append(key)
    # Every explicit action and reason remains visible. No history truncation.
    return {'contract':CONTRACT,'current_frame':memory['current_frame'],
            'steps':steps, 'judgments':list(judgments.values()),
            'entry_frame_id':memory['entry_frame_id'],
            'entry_search':{'queries':memory['frames'][memory['entry_frame_id']]['data'].get('search_queries',[]) if memory['entry_frame_id'] else [],
                'reason':'현재 질문의 원문 근거를 찾기 위한 실행된 검색 계획','reason_origin':'SYSTEM_ENTRY'},
            'memory_rule':'과거 메뉴로 돌아가도 확보 원문·채택·보류·후속 판단을 되돌리지 않는다'}

def compact(chain, *, tail=8, reason_chars=200, brief=False):
    """Model-facing projection: every step stays visible, older steps shortened.

    The durable chain (context) is unchanged; only steps before the last `tail`
    drop target objects, notes and judgment detail while keeping action, reason,
    queries and the recorded outcome."""
    steps=(chain or {}).get('steps',[])
    if brief:
        rows=[]
        for step in steps:
            row={k:deepcopy(step[k]) for k in ('id','number','action','status','queries','structure_filter','outcome','progress','basis_refs') if k in step}
            row['reason']=(step.get('reason') or '')[:reason_chars]
            row['targets']=[{k:deepcopy(t[k]) for k in ('id','label') if k in t} |
                {'location':{k:deepcopy(v) for k,v in t.get('identity',{}).items()
                             if k in ('document_id','source_id','unit_id','branch_id','frame_id','page','scope') and not isinstance(v,(dict,list))}}
                for t in step.get('targets',[]) if isinstance(t,dict)]
            rows.append(row)
        return {k:deepcopy(v) for k,v in (chain or {}).items() if k not in ('steps','judgments')} | {
            'steps':rows,'compacted_steps':len(rows),
            'compaction_rule':'Every action, target, query and recorded result remains; full decisions and reasons stay in the durable journal.'}
    if len(steps)<=tail:return chain
    older=[]
    for step in steps[:-tail]:
        row={'number':step.get('number'),'action':step.get('action'),'status':step.get('status'),
             'reason':(step.get('reason') or '')[:reason_chars],
             'targets':[t.get('label') for t in step.get('targets',[]) if isinstance(t,dict)]}
        for key in ('queries','outcome','progress'):
            if step.get(key):row[key]=deepcopy(step[key])
        older.append(row)
    recent=deepcopy(steps[-tail:])
    refs={r for s in recent for r in s.get('judgment_refs',[])}
    return {**{k:deepcopy(v) for k,v in chain.items() if k not in ('steps','judgments')},
            'steps':older+recent,'judgments':[deepcopy(j) for j in chain.get('judgments',[]) if j['id'] in refs],
            'compacted_steps':len(older),
            'compaction_rule':'older steps keep action, reason, queries and outcome; full detail stays in the durable journal'}

def points(p):
    rows=[]
    for f in sorted(state(p)['frames'].values(), key=lambda f:f['number']):
        d=f['data'];rows.append({'id':f['id'],'number':f['number'],'kind':f['kind'],
            'arrived_after':f['arrived_after'],'search_queries':d.get('search_queries',[]),
            'laws':[l['name'] for l in d.get('laws',[])],
            'originals':[s.get('heading',s.get('source_id')) for s in d.get('sources',[])],
            'reference_groups':len(d.get('groups',[]))})
    return rows
